begin;
create type public.submission_status as enum('draft','submitted','under_review','approved','rejected','withdrawn');
create type public.offer_status as enum('submitted','under_review','accepted','rejected','withdrawn','expired');
create type public.lease_status as enum('draft','active','ended','cancelled');
create type public.property_service_kind as enum('diaspora','investment','valuation','concierge');

create table public.property_submissions(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id),branch_id uuid references public.branches(id),title text not null check(char_length(title) between 5 and 180),listing_type public.listing_type not null,property_type text not null,address text not null,asking_price numeric(14,2) check(asking_price>=0),bedrooms integer check(bedrooms>=0),bathrooms integer check(bathrooms>=0),description text not null check(char_length(description) between 20 and 10000),status public.submission_status not null default'draft',review_notes text,reviewed_by uuid references public.profiles(id),submitted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.property_submission_documents(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.property_submissions(id) on delete cascade,storage_path text not null unique,document_type text not null,original_name text not null,created_at timestamptz not null default now());
create table public.property_ownerships(property_id uuid not null references public.properties(id) on delete cascade,owner_id uuid not null references public.profiles(id) on delete cascade,ownership_percent numeric(5,2) not null default 100 check(ownership_percent>0 and ownership_percent<=100),verified_at timestamptz,primary key(property_id,owner_id));
create table public.leases(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id),landlord_id uuid not null references public.profiles(id),tenant_id uuid not null references public.profiles(id),status public.lease_status not null default'draft',starts_on date not null,ends_on date not null check(ends_on>starts_on),rent_amount numeric(14,2) not null check(rent_amount>=0),currency char(3) not null default'ZMW',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.maintenance_requests(id uuid primary key default gen_random_uuid(),lease_id uuid not null references public.leases(id) on delete cascade,created_by uuid not null references public.profiles(id),title text not null check(char_length(title) between 3 and 180),description text not null check(char_length(description) between 10 and 4000),priority text not null default'normal' check(priority in('low','normal','high','urgent')),status text not null default'open' check(status in('open','assigned','in_progress','resolved','closed')),assigned_to uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.property_offers(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id),buyer_id uuid not null references public.profiles(id),amount numeric(14,2) not null check(amount>0),currency char(3) not null default'ZMW',conditions text check(char_length(conditions)<=4000),status public.offer_status not null default'submitted',expires_at timestamptz,reviewed_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(expires_at is null or expires_at>created_at));
create table public.transaction_milestones(id uuid primary key default gen_random_uuid(),offer_id uuid not null references public.property_offers(id) on delete cascade,title text not null,due_at timestamptz,completed_at timestamptz,position integer not null default 0,created_at timestamptz not null default now());
create table public.property_service_requests(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.profiles(id),kind public.property_service_kind not null,requirements text not null check(char_length(requirements) between 20 and 4000),budget numeric(14,2) check(budget>=0),preferred_contact text not null default'email' check(preferred_contact in('email','phone','whatsapp','video')),timezone text check(char_length(timezone)<=100),assigned_to uuid references public.profiles(id),status text not null default'new' check(status in('new','assigned','in_progress','completed','closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index submissions_owner on public.property_submissions(owner_id,created_at desc);create index leases_parties on public.leases(tenant_id,landlord_id,status);create index maintenance_lease on public.maintenance_requests(lease_id,status);create index offers_property on public.property_offers(property_id,status,created_at desc);create index service_requests_queue on public.property_service_requests(kind,status,created_at desc);
create trigger set_property_submissions_updated_at before update on public.property_submissions for each row execute function public.set_updated_at();create trigger set_leases_updated_at before update on public.leases for each row execute function public.set_updated_at();create trigger set_maintenance_requests_updated_at before update on public.maintenance_requests for each row execute function public.set_updated_at();create trigger set_property_offers_updated_at before update on public.property_offers for each row execute function public.set_updated_at();create trigger set_property_service_requests_updated_at before update on public.property_service_requests for each row execute function public.set_updated_at();

alter table public.property_submissions enable row level security;alter table public.property_submission_documents enable row level security;alter table public.property_ownerships enable row level security;alter table public.leases enable row level security;alter table public.maintenance_requests enable row level security;alter table public.property_offers enable row level security;alter table public.transaction_milestones enable row level security;alter table public.property_service_requests enable row level security;
create policy submissions_owner_read on public.property_submissions for select using(owner_id=auth.uid() or public.is_staff());create policy submissions_owner_insert on public.property_submissions for insert with check(owner_id=auth.uid() and status in('draft','submitted') and reviewed_by is null and review_notes is null);create policy submissions_owner_update on public.property_submissions for update using(owner_id=auth.uid() and status in('draft','submitted')) with check(owner_id=auth.uid() and status in('draft','submitted','withdrawn') and reviewed_by is null and review_notes is null);create policy submissions_staff_update on public.property_submissions for update using(public.is_staff()) with check(public.is_staff());
create policy submission_documents_read on public.property_submission_documents for select using(exists(select 1 from public.property_submissions s where s.id=submission_id and(s.owner_id=auth.uid() or public.is_staff())));create policy submission_documents_owner_insert on public.property_submission_documents for insert with check(split_part(storage_path,'/',1)=auth.uid()::text and split_part(storage_path,'/',2)=submission_id::text and exists(select 1 from public.property_submissions s where s.id=submission_id and s.owner_id=auth.uid() and s.status in('draft','submitted')));
create policy ownership_parties_read on public.property_ownerships for select using(owner_id=auth.uid() or public.is_staff());create policy ownership_staff_write on public.property_ownerships for all using(public.is_staff()) with check(public.is_staff());
create policy leases_parties_read on public.leases for select using(landlord_id=auth.uid() or tenant_id=auth.uid() or public.is_staff());create policy leases_staff_write on public.leases for all using(public.is_staff()) with check(public.is_staff());
create policy maintenance_parties_read on public.maintenance_requests for select using(public.is_staff() or exists(select 1 from public.leases l where l.id=lease_id and auth.uid() in(l.landlord_id,l.tenant_id)));create policy maintenance_parties_insert on public.maintenance_requests for insert with check(created_by=auth.uid() and status='open' and assigned_to is null and exists(select 1 from public.leases l where l.id=lease_id and auth.uid() in(l.landlord_id,l.tenant_id)));create policy maintenance_staff_update on public.maintenance_requests for update using(public.is_staff()) with check(public.is_staff());
create policy offers_parties_read on public.property_offers for select using(buyer_id=auth.uid() or public.is_staff() or exists(select 1 from public.property_ownerships o where o.property_id=property_offers.property_id and o.owner_id=auth.uid()));create policy offers_buyer_insert on public.property_offers for insert with check(buyer_id=auth.uid() and status='submitted' and reviewed_by is null and(expires_at is null or expires_at>now()) and exists(select 1 from public.properties p where p.id=property_id and p.status='published' and p.is_available));create policy offers_buyer_withdraw on public.property_offers for update using(buyer_id=auth.uid() and status in('submitted','under_review')) with check(buyer_id=auth.uid() and status='withdrawn');create policy offers_staff_update on public.property_offers for update using(public.is_staff()) with check(public.is_staff());
create policy milestones_parties_read on public.transaction_milestones for select using(exists(select 1 from public.property_offers o where o.id=offer_id and(o.buyer_id=auth.uid() or public.is_staff() or exists(select 1 from public.property_ownerships own where own.property_id=o.property_id and own.owner_id=auth.uid()))));create policy milestones_staff_write on public.transaction_milestones for all using(public.is_staff()) with check(public.is_staff());
create policy service_requests_owner_read on public.property_service_requests for select using(customer_id=auth.uid() or public.is_staff());create policy service_requests_owner_insert on public.property_service_requests for insert with check(customer_id=auth.uid() and status='new' and assigned_to is null);create policy service_requests_staff_update on public.property_service_requests for update using(public.is_staff()) with check(public.is_staff());

create function public.enforce_offer_withdrawal() returns trigger language plpgsql security invoker set search_path='' as $$
begin
  if not public.is_staff() and old.buyer_id=auth.uid() then
    if new.status<>'withdrawn' or (to_jsonb(new)-'status'-'updated_at') is distinct from (to_jsonb(old)-'status'-'updated_at') then raise exception 'customers may only withdraw an unchanged offer' using errcode='42501'; end if;
  elsif public.is_staff() then
    if (to_jsonb(new)-'status'-'reviewed_by'-'updated_at') is distinct from (to_jsonb(old)-'status'-'reviewed_by'-'updated_at') then raise exception 'staff may not alter submitted offer terms' using errcode='42501'; end if;
    if old.status<>new.status and not (
      (old.status='submitted' and new.status in('under_review','accepted','rejected','expired')) or
      (old.status='under_review' and new.status in('accepted','rejected','expired'))
    ) then raise exception 'invalid offer status transition' using errcode='23514'; end if;
  end if;
  return new;
end $$;
create trigger enforce_offer_withdrawal before update on public.property_offers for each row execute function public.enforce_offer_withdrawal();

create function public.audit_ecosystem_change() returns trigger language plpgsql security definer set search_path='' as $$
begin
  insert into public.audit_logs(actor_id,action,table_name,record_id,old_data,new_data)
  values(auth.uid(),lower(tg_op),tg_table_name,coalesce(new.id,old.id),
    case when tg_op='INSERT' then null else jsonb_build_object('status',old.status) end,
    case when tg_op='DELETE' then null else jsonb_build_object('status',new.status) end);
  return coalesce(new,old);
end $$;
create trigger audit_property_submission after insert or update of status on public.property_submissions for each row execute function public.audit_ecosystem_change();
create trigger audit_property_offer after insert or update of status on public.property_offers for each row execute function public.audit_ecosystem_change();
create trigger audit_maintenance_request after insert or update of status on public.maintenance_requests for each row execute function public.audit_ecosystem_change();
create trigger audit_property_service_request after insert or update of status on public.property_service_requests for each row execute function public.audit_ecosystem_change();

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('owner-submission-documents','owner-submission-documents',false,10485760,array['application/pdf','image/jpeg','image/png']) on conflict(id) do nothing;
create policy owner_submission_storage_read on storage.objects for select using(bucket_id='owner-submission-documents' and(public.is_staff() or (storage.foldername(name))[1]=auth.uid()::text));create policy owner_submission_storage_insert on storage.objects for insert with check(bucket_id='owner-submission-documents' and(storage.foldername(name))[1]=auth.uid()::text);
create policy owner_submission_storage_delete on storage.objects for delete using(bucket_id='owner-submission-documents' and(storage.foldername(name))[1]=auth.uid()::text);
commit;
